INSERT INTO public.mock_test_questions (test_id, question_number, question_text, type, metadata, correct_answer, points_a, points_b)
        VALUES ('4f88e25d-7521-4d37-885e-7a932b1f3c3a', 24, '[1,3 ball]  Ikki to‘g‘ri chiziqning kesishishidan hosil bo‘lgan qo‘shni burchaklarning ayirmasi   20 ◦   ga teng bo‘lsa,   bu burchaklardan kichigini toping.', 'multiple_choice', '{"options":["90 ◦","80 ◦","60 ◦","70 ◦  6\nMatematika fanidan namunaviy test topshiriqlari"]}', '"A"', null, null);
INSERT INTO public.mock_test_questions (test_id, question_number, question_text, type, metadata, correct_answer, points_a, points_b)
        VALUES ('4f88e25d-7521-4d37-885e-7a932b1f3c3a', 25, '[1,3 ball]  ABC   teng yonli   ( AB   =   BC )   uchburchakning   BD   medianasi uzunligi 4 cm ga teng. Agar   ABD  uchburchak perimetri 12 cm ga teng bo‘lsa,   ABC   uchburchak perimetrini (cm) toping.', 'multiple_choice', '{"options":["9","8","16","18"]}', '"A"', null, null);
