        VALUES ('4f88e25d-7521-4d37-885e-7a932b1f3c3a', 26, '[2,2 ball]  Aylana   13 : 14 : 9   nisbatda uchta yoyga bo‘lingan va bo‘linish nuqtalari tutashtirilib uchburchak hosil qilingan. Agar hosil bo‘lgan uchburchakning kichik tomoni   4  √ 12   cm ga teng bo‘lsa,   aylanaga tashqi chizilgan muntazam uchburchakning yuzini (cm 2 ) toping.', 'multiple_choice', '{"options":["2   4  √ 3","9","36","3 √ 3"]}', '"A"', null, null);
