        VALUES ('4f88e25d-7521-4d37-885e-7a932b1f3c3a', 27, '[2,2 ball]  A D   C B F K x   x  3 y y  Chizmadagi   ABCD   parallelogrammning yuzi 64 cm 2   ga teng bo‘lsa,   F KCD   to‘rtburchakning yuzini (cm 2 ) toping.  Bunda   AF  F D   = 3 ,   AK  KB   = 1   ga teng.', 'multiple_choice', '{"options":["52","36","48","28  7\nMatematika fanidan namunaviy test topshiriqlari"]}', '"A"', null, null);
