        VALUES ('4f88e25d-7521-4d37-885e-7a932b1f3c3a', 28, '[2,2 ball]  Muntazam sakkizburchakka ichki va tashqi aylanalar chizilgan. Agar ichki chizilgan aylananing radiusi  r   = 2 +   √ 2   cm bo‘lsa,   bu aylanalar hosil qilgan halqaning yuzini (cm 2 ) toping.', 'multiple_choice', '{"options":["4 π","8 π","2 π","√ 2 π"]}', '"A"', null, null);
INSERT INTO public.mock_test_questions (test_id, question_number, question_text, type, metadata, correct_answer, points_a, points_b)
        VALUES ('4f88e25d-7521-4d37-885e-7a932b1f3c3a', 29, '[2,2 ball]  α   tekislik va uni kesib o‘tmaydigan   AB   kesma berilgan.   AB   kesmaning uchlaridan   α   tekislikkacha bo‘lgan eng qisqa masofalar   AA 1   = 2   cm va   BB 1   = 7   cm ga teng.  A   uchidan boshlab hisoblaganda   AB   kesmani   3 : 2   nisbatda bo‘luvchi nuqtadan   α  tekislikkacha bo‘lgan eng qisqa masofani (cm) toping.', 'multiple_choice', '{"options":["5","3","4,5","4"]}', '"A"', null, null);
