        VALUES ('4f88e25d-7521-4d37-885e-7a932b1f3c3a', 31, '[2,2 ball]  U   =   { x | −   10   ≤   x   ≤   10 , x   ∈   Z }   universal to‘plam hamda uning   A   =   { x | −   7   ≤   x   ≤   3 , x   ∈   Z }   va  B   =   { x | −   3   ≤   x   ≤   7 , x   ∈   Z }   qism to‘plamlari bo‘lsin.  ( A   ∪   B ) ′   to‘plamning elementlari sonini toping.   Bunda   ( A   ∪   B ) ′   to‘plam   A   ∪   B   to‘plamning to‘ldiruvchisi.', 'multiple_choice', '{"options":["2","6","8","4  8\nMatematika fanidan namunaviy test topshiriqlari"]}', '"A"', null, null);
